def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    opp_c = 0
    for i in range(n):
        if history[i][1] == 'C':
            opp_c += 1
    opp_d = n - opp_c

    if opp_d == 0:
        return 'C'
    if opp_c == 0:
        return 'D'

    last_me, last_opp = history[n - 1]
    rate = opp_c / float(n)

    w = n if n < 10 else 10
    start = n - w
    d10 = 0
    bad10 = 0
    for i in range(start, n):
        if history[i][1] == 'D':
            d10 += 1
            if i == 0 or history[i - 1][0] == 'C':
                bad10 += 1

    if rate <= 0.30 or d10 >= 8:
        return 'D'

    if last_opp == 'D':
        if last_me == 'C':
            return 'D'

        dd_streak = 0
        for i in range(n - 1, -1, -1):
            if history[i][0] == 'D' and history[i][1] == 'D':
                dd_streak += 1
            else:
                break

        if rate > 0.50 and d10 <= 6 and bad10 <= 1:
            if dd_streak >= 4 and rng.random() < 0.45:
                return 'C'
            if rng.random() < 0.20:
                return 'C'

        return 'D'

    if last_me == 'D':
        if d10 <= 2 and bad10 <= 1 and rate >= 0.50:
            return 'C'
        if bad10 == 0 and d10 <= 4 and rate >= 0.45:
            return 'C'

    if rate >= 0.85 and d10 <= 5 and bad10 <= 1:
        return 'C'

    if rate >= 0.70 and d10 <= 3 and bad10 <= 1:
        return 'C'

    if d10 >= 3 and rng.random() < 0.65:
        return 'D'

    if rate <= 0.55 and rng.random() < 0.70:
        return 'D'

    if rate >= 0.65:
        return 'C'

    return 'C' if rng.random() < 0.55 else 'D'
